  function filterManualResults(){const q=manualQuery.trim().toLowerCase(),entries=[...$("station-panel").querySelectorAll(".exo-manual-entry")];let n=0;entries.forEach(e=>{const m=!q||(e.dataset.manualSearch||"").includes(q);e.hidden=!m;if(m)n++;});const c=$("station-panel").querySelector("[data-manual-count]"),empty=$("station-panel").querySelector("[data-manual-empty]");if(c)c.textContent=`${n} / ${entries.length} entries`;if(empty)empty.hidden=n!==0;}
