  function renderStation(){const d=STATIONS[activeStation];$("station-panel").innerHTML=`<div class="exo-station-head station-head-${d.theme}"><div class="exo-station-title"><span class="exo-kicker">${state.profile.name} procedural watchstation</span><h2>${d.label}</h2><p>${d.description}</p></div><div class="exo-station-readout">${d.readouts(state).map(([l,v])=>`<div class="exo-readout-chip"><span>${l}</span><strong>${v}</strong></div>`).join("")}</div></div><div class="exo-station-body"><div class="exo-control-bank exo-procedure-bank">${procedureControls(d)}</div>${tacticalDisplay(d.display)}</div><button type="button" class="exo-manual-launch" data-manual-open><span class="exo-manual-book-icon"><i></i></span><b>OPS MANUAL</b><small>${d.procedures.length} ENTRIES</small></button>${manualOpen?manualOverlay(d):""}`;}
