  const classify=q=>q>=95?"by-the-book":q>=82?"minor deviation":q>=65?"workable sequence":q>=45?"poor sequence":"incorrect / hazardous sequence",baseDifficulty=q=>q>=95?5:q>=82?6:q>=65?7:q>=45?8:9;

